def total(n):
    print("호출", n)
    if n == 0:
        result = 0
    else:
        result = n + total(n - 1)
    print("반환", n, result)
    return result

print("결과", total(3))

def recursive_sum(n):
    if n < 0:
        raise ValueError("n must be nonnegative")
    if n == 0:
        return 0
    return n + recursive_sum(n - 1)

print(recursive_sum(4))
print(recursive_sum(0))
try:
    recursive_sum(-1)
except ValueError:
    print("ValueError")

def sum_recursive(values):
    def visit(index):
        if index == len(values):
            return 0
        return values[index] + visit(index + 1)
    return visit(0)

values = [3, -2, 4]
print(sum_recursive(values), values)
print(sum_recursive([]))
print(sum_recursive([7]))

def recursive_contains(values, target):
    def visit(index):
        if index == len(values):
            return False
        if values[index] == target:
            return True
        return visit(index + 1)
    return visit(0)

print(recursive_contains([2, 5, 2], 5))
print(recursive_contains([2, 5, 2], 8))
print(recursive_contains([], 2))

def recursive_call_trace(n):
    if n < 0:
        raise ValueError("n must be nonnegative")
    events = []
    def visit(value):
        events.append(("enter", value))
        if value > 0:
            visit(value - 1)
        events.append(("leave", value))
    visit(n)
    return events

print(recursive_call_trace(2))
print(recursive_call_trace(0))
try:
    recursive_call_trace(-1)
except ValueError:
    print("ValueError")
